75:         public static void OnTrigger(AbilityTrigger entity, TriggerContext context)
76:         {
77:             var newContext = context;
78:             newContext.AbilityTrigger = entity;
79:             context = newContext;
80:             var abilityTrigger = entity;
81: 
82:             var source = context.TriggerSource;
83:             var target = context.Target;
84:             if (target == null && source != null)
85:             {
86:                 target = source;
87:             }
88:             if (target == null)
89:             {
90:                 target = entity.ParentEntity;
91:             }
92: 
93:             var stateCheckResult = true;
94: 
95:             /// 这里是状态判断，状态判断是判断目标的状态是否满足条件，满足才能触发效果
96:             if (abilityTrigger.GetComponent<TriggerStateCheckComponent>() is { } component)
97:             {
98:                 stateCheckResult = TriggerStateCheckSystem.CheckTargetState(abilityTrigger, target);
99:             }
100: 
101:             /// 条件满足则触发效果
102:             if (stateCheckResult)
103:             {
104:                 foreach (var item in entity.TriggerConfig.TriggerEffects)
105:                 {
106:                     var effects = entity.OwnerAbility.AbilityEffects;
107:                     for (int i = 0; i < effects.Count; i++)
108:                     {
109:                         if (i == (int)item.EffectApplyType - 1 || item.EffectApplyType == EffectApplyType.AllEffects)
110:                         {
111:                             var abilityEffect = effects[i];
112: 
113:                             if (entity.OwnerEntity.EffectAssignAbility.TryMakeAction(out var effectAssign))
114:                             {
115:                                 effectAssign.AbilityEffect = abilityEffect;
116:                                 effectAssign.AssignTarget = target;
117:                                 effectAssign.SourceAbility = entity.OwnerAbility;
118:                                 effectAssign.TriggerContext = context;
119:                                 AssignActionSystem.Execute(effectAssign);
120:                             }
121:                         }
122:                     }
123:                 }
124:             }

