28:         private static bool ActionCheckProcess(DamageAction entity)
29:         {
30:             if (entity.DamageSource == DamageSource.Attack)
31:             {
32:                 entity.IsCritical = (GameUtils.RandomHelper.RandomRate() / 100f) < entity.Creator.GetComponent<AttributeComponent>().CriticalProbability.Value;
33:                 var Atk = entity.Creator.GetComponent<AttributeComponent>().Attack.Value;
34:                 var Def = entity.Target.GetComponent<AttributeComponent>().Defense.Value;
35:                 var coeff = Atk / (Atk + Def);
36:                 var Dam1 = Atk * coeff;
37: 
38:                 entity.DamageValue = Mathf.CeilToInt(Dam1);
39:                 if (entity.IsCritical)
40:                 {
41:                     entity.DamageValue = Mathf.CeilToInt(entity.DamageValue * 1.5f);
42:                 }
43:             }
44: 
45:             if (entity.DamageSource == DamageSource.Skill)
46:             {
47:                 if (entity.DamageEffect.CanCrit)
48:                 {
49:                     entity.IsCritical = (GameUtils.RandomHelper.RandomRate() / 100f) < entity.Creator.GetComponent<AttributeComponent>().CriticalProbability.Value;
50:                 }
51:                 entity.DamageValue = EffectDamageSystem.GetDamageValue(entity.SourceAssignAction.AbilityEffect);
52:                 if (entity.IsCritical)
53:                 {
54:                     entity.DamageValue = Mathf.CeilToInt(entity.DamageValue * 1.5f);
55:                 }
56:             }
57: 
58:             if (entity.DamageSource == DamageSource.Buff)
59:             {
60:                 if (entity.DamageEffect.CanCrit)
61:                 {
62:                     entity.IsCritical = (GameUtils.RandomHelper.RandomRate() / 100f) < entity.Creator.GetComponent<AttributeComponent>().CriticalProbability.Value;
63:                 }
64:                 entity.DamageValue = EffectDamageSystem.GetDamageValue(entity.SourceAssignAction.AbilityEffect);
65:             }
66: 
67:             return true;
68:         }
