55:     public class ActionSystem
56:     {
57:         public static void ExecuteAction<T>(T entity, Func<T, bool> actionProcess, Func<T, bool> actionApply) where T : EcsEntity, IActionExecute
58:         {
59:             ActionSystem.BeforeExecuteAction(entity.Creator, x => x.BeforeExecuteAction(entity.Creator, entity));
60:             ActionSystem.BeforeSufferAction(entity.Target, x => x.BeforeSufferAction(entity.Target, entity));
61: 
62:             var result = actionProcess.Invoke(entity);
63: 
64:             if (result)
65:             {
66:                 ActionSystem.BeforeCauseApply(entity.Creator, x => x.BeforeCauseApply(entity.Creator, entity));
67:                 ActionSystem.BeforeReceiveApply(entity.Target, x => x.BeforeReceiveApply(entity.Target, entity));
68: 
69:                 var applyResult = actionApply.Invoke(entity);
70: 
71:                 if (applyResult)
72:                 {
73:                     ActionSystem.AfterCauseApply(entity.Creator, x => x.AfterCauseApply(entity.Creator, entity));
74:                     ActionSystem.AfterReceiveApply(entity.Target, x => x.AfterReceiveApply(entity.Target, entity));
75:                 }
76:             }
77: 
78:             ActionSystem.AfterExecuteAction(entity.Creator, x => x.AfterExecuteAction(entity.Creator, entity));
79:             ActionSystem.AfterSufferAction(entity.Target, x => x.AfterSufferAction(entity.Target, entity));
80:         }

